// Uses the production HTML generated by the extension, served locally with a VS Code API bridge.
const {chromium}=require('playwright-core'),http=require('node:http'),fs=require('node:fs/promises'),path=require('node:path'),assert=require('node:assert/strict');
const {makeHost}=require('./host-harness.cjs');
(async()=>{
  let host,browser;const media=path.resolve(__dirname,'../media');let html='';
  const server=http.createServer(async(req,res)=>{try{if(req.url==='/'){res.setHeader('content-type','text/html');res.end(html);return;}const name=path.basename(new URL(req.url,'http://localhost').pathname);const bytes=await fs.readFile(path.join(media,name));res.setHeader('content-type',name.endsWith('.js')?'application/javascript':name.endsWith('.css')?'text/css':name.endsWith('.png')?'image/png':'text/plain');res.end(bytes);}catch{res.statusCode=404;res.end();}});
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const base=`http://127.0.0.1:${server.address().port}`;
  try{
    host=await makeHost(path.resolve(__dirname,'../..'),base+'/media');html=host.view.html;
    const executable=process.env.FRC_BROWSER||'C:/Program Files/Google/Chrome/Application/chrome.exe';
    browser=await chromium.launch({executablePath:executable,headless:true});const page=await browser.newPage({viewport:{width:360,height:820},deviceScaleFactor:1});const errors=[];
    page.on('pageerror',error=>errors.push(error.message));
    await page.exposeFunction('vscodeMessage',async message=>{await host.view.receive(message);const data=host.messages.findLast(m=>m.type==='data');await page.evaluate(data=>window.postMessage(data,'*'),data);});
    await page.addInitScript(()=>{let state;window.acquireVsCodeApi=()=>({getState:()=>state,setState:value=>{state=value;},postMessage:message=>window.vscodeMessage(message)});});
    await page.goto(base);await page.waitForFunction(()=>document.querySelector('#path').options.length>1&&document.querySelector('#image').naturalWidth===3508);
    await page.selectOption('#path',{label:'Drive Forward'});await page.waitForFunction(()=>document.querySelector('#pose').textContent.includes('X 3.59'));
    await page.locator('#timeline').evaluate(el=>{el.value='.5';el.dispatchEvent(new Event('input'));});assert.ok((await page.locator('#pose').textContent()).includes('preview 3.00 m/s'));
    await page.selectOption('#alliance','red');await page.selectOption('#auto',{label:'Worlds Auto'});await page.waitForFunction(()=>document.querySelector('#routine').textContent.includes('Shoot First 8'));assert.ok((await page.locator('#routine').textContent()).includes('parallel'));
    const bounds=await page.locator('#field').boundingBox();assert.ok(bounds.width>300&&bounds.height>160);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
    await page.mouse.move(bounds.x+bounds.width/2,bounds.y+bounds.height/2);await page.mouse.wheel(0,-300);await page.screenshot({path:path.resolve(__dirname,'../out/sidebar-preview.png')});
    await page.locator('#fit').click();await page.selectOption('#auto','');await page.selectOption('#path',{label:'Drive Forward'});await page.selectOption('#alliance','blue');await page.locator('#edit').click();assert.equal(await page.locator('#path').isDisabled(),true);
    const rect=await page.locator('#field').boundingBox();const s=Math.min(rect.width/3508,rect.height/1814),ox=(rect.width-3508*s)/2,oy=(rect.height-1814*s)/2;
    const x=rect.x+ox+(3.592666666666667+.5)*200*s,y=rect.y+oy+(8.57-7.338366666666666)*200*s;
    await page.mouse.move(x,y);await page.mouse.down();await page.mouse.move(x+15,y+10,{steps:3});await page.mouse.up();assert.equal(await page.locator('#save').isEnabled(),true);await page.locator('#discard').click();assert.equal(await page.locator('#save').isDisabled(),true);
    await page.setViewportSize({width:1200,height:850});await page.screenshot({path:path.resolve(__dirname,'../out/editor-preview.png')});assert.deepEqual(errors,[]);
    console.log('Browser checks passed: production HTML/CSP, field image, narrow layout, selections, timeline, routine tree, zoom, waypoint drag/discard, full-width layout.');
  }finally{await browser?.close();host?.dispose();await new Promise(resolve=>server.close(resolve));}
})().catch(error=>{console.error(error);process.exitCode=1;});
